const wire = JSON.stringify(user);
// wire is now a plain string: '{"id":42,"name":"Riya","active":true}'
// safe to send over HTTP, write to a file, or store in a cache

const restored = JSON.parse(wire);
// restored is a fresh object, structurally equal to the original

